        {
            "type": 12,
            "content": {
                "version": "NotebookGroup/1.0",
                "groupType": "editable",
                "items": [
                    {
                        "type": 1,
                        "content": {
                            "json": "### Executive Expiry Breakdown & Timeline\r\nVisual distribution of certificate lifecycles across status tiers, subscriptions, and geographic regions."
                        },
                        "name": "text - Overview Intro"
                    },
                    {
                        "type": 3,
                        "content": {
                            "version": "KqlItem/1.0",
                            "query": "resources\r\n| where type =~ 'microsoft.web/certificates'\r\n| extend ExpirationDate = todatetime(properties.expirationDate)\r\n| extend DaysRemaining = datetime_diff('day', ExpirationDate, now())\r\n| extend StatusTier = case(\r\n    isnull(ExpirationDate), 'Unknown',\r\n    DaysRemaining < 0, '1. Expired',\r\n    DaysRemaining <= 30, '2. Critical (< 30 Days)',\r\n    DaysRemaining <= 60, '3. Warning (31 - 60 Days)',\r\n    DaysRemaining <= 90, '4. Attention (61 - 90 Days)',\r\n    '5. Healthy (> 90 Days)'\r\n)\r\n| summarize Count = count() by StatusTier\r\n| sort by StatusTier asc",
                            "size": 0,
                            "title": "Certificates by Expiry Status Tier",
                            "queryType": 1,
                            "resourceType": "microsoft.resourcegraph/resources",
                            "crossComponentResources": [
                                "{Subscriptions}"
                            ],
                            "visualization": "piechart"
                        },
                        "name": "query - Status Tier Pie Chart",
                        "customWidth": "50"
                    },
                    {
                        "type": 3,
                        "content": {
                            "version": "KqlItem/1.0",
                            "query": "resources\r\n| where type =~ 'microsoft.web/certificates'\r\n| extend ExpirationDate = todatetime(properties.expirationDate)\r\n| extend DaysRemaining = datetime_diff('day', ExpirationDate, now())\r\n| extend Category = iff(DaysRemaining < 0, 'Expired', iff(DaysRemaining <= 90, 'Expiring Soon', 'Healthy'))\r\n| summarize Count = count() by subscriptionId, Category",
                            "size": 0,
                            "title": "Expiry Distribution by Subscription",
                            "queryType": 1,
                            "resourceType": "microsoft.resourcegraph/resources",
                            "crossComponentResources": [
                                "{Subscriptions}"
                            ],
                            "visualization": "barchart"
                        },
                        "name": "query - Subscription Bar Chart",
                        "customWidth": "50"
                    },
                    {
                        "type": 3,
                        "content": {
                            "version": "KqlItem/1.0",
                            "query": "resources\r\n| where type =~ 'microsoft.web/certificates'\r\n| summarize Count = count() by location\r\n| sort by Count desc",
