                        },
                        "name": "query - Map of Certificates"
                    },
                    {
                        "type": 3,
                        "content": {
                            "version": "KqlItem/1.0",
                            "query": "resources\r\n| where type =~ 'microsoft.web/certificates'\r\n| extend ExpirationDate = todatetime(properties.expirationDate)\r\n| extend DaysRemaining = datetime_diff('day', ExpirationDate, now())\r\n| where DaysRemaining <= 90\r\n| extend Urgency = case(\r\n    DaysRemaining < 0, 'Expired',\r\n    DaysRemaining <= 30, 'Critical (< 30 Days)',\r\n    DaysRemaining <= 60, 'Warning (31 - 60 Days)',\r\n    'Attention (61 - 90 Days)'\r\n)\r\n| extend Subject = tostring(properties.subjectName)\r\n| extend Issuer = tostring(properties.issuer)\r\n| extend Thumbprint = tostring(properties.thumbprint)\r\n| extend KeyVaultId = tostring(properties.keyVaultId)\r\n| project Certificate = id, Subject, Issuer, ExpirationDate, DaysRemaining, Urgency, Thumbprint, KeyVaultId, resourceGroup, subscriptionId\r\n| sort by DaysRemaining asc",
                            "size": 2,
                            "title": "Urgent Action Required: Expired or Expiring within 90 Days",
                            "noDataMessage": "All certificates are valid and healthy (> 90 days remaining).",
                            "showExportToExcel": true,
                            "queryType": 1,
                            "resourceType": "microsoft.resourcegraph/resources",
                            "crossComponentResources": [
                                "{Subscriptions}"
                            ],
                            "visualization": "table",
                            "gridSettings": {
                                "filter": true,
                                "sortBy": [
                                    {
                                        "itemKey": "DaysRemaining",
                                        "sortOrder": 1
                                    }
                                ],
                                "formatters": [
                                    {
                                        "columnMatch": "Certificate",
