                "groupType": "editable",
                "items": [
                    {
                        "type": 1,
                        "content": {
                            "json": "### App Service Certificate Orders (`microsoft.web/certificateorders`)\r\nTracks domain certificate orders created via the Azure Portal, including auto-renew status, issuance state, and renewal deadlines."
                        },
                        "name": "text - Certificate Orders Intro"
                    },
                    {
