                        "content": {
                            "version": "KqlItem/1.0",
                            "query": "resources\r\n| where type =~ 'microsoft.web/certificateorders'\r\n| extend ExpirationTime = todatetime(properties.expirationTime)\r\n| extend DaysRemaining = datetime_diff('day', ExpirationTime, now())\r\n| extend ExpiryStatus = case(\r\n    isnull(ExpirationTime), 'Unknown',\r\n    DaysRemaining < 0, 'Expired',\r\n    DaysRemaining <= 30, 'Critical (< 30 Days)',\r\n    DaysRemaining <= 60, 'Warning (31 - 60 Days)',\r\n    DaysRemaining <= 90, 'Attention (61 - 90 Days)',\r\n    'Healthy (> 90 Days)'\r\n)\r\n| extend ExpiryFilterKey = case(\r\n    isnull(ExpirationTime), 'Unknown',\r\n    DaysRemaining < 0, 'Expired',\r\n    DaysRemaining <= 30, 'Critical',\r\n    DaysRemaining <= 60, 'Warning',\r\n    DaysRemaining <= 90, 'Attention',\r\n    'Healthy'\r\n)\r\n| where '{ExpiryThreshold}' == 'all' or ExpiryFilterKey == '{ExpiryThreshold}'\r\n| extend Domain = tostring(properties.distinguishedName)\r\n| extend ProductType = tostring(properties.productType)\r\n| extend AutoRenew = tostring(properties.autoRenew)\r\n| extend OrderStatus = tostring(properties.status)\r\n| extend ProvisioningState = tostring(properties.provisioningState)\r\n| extend KeyVaultId = tostring(properties.keyVaultId)\r\n| project Order = id, Domain, ProductType, AutoRenew, OrderStatus, ProvisioningState, ExpirationTime, DaysRemaining, ExpiryStatus, KeyVaultId, resourceGroup, subscriptionId\r\n| sort by DaysRemaining asc",
