                        "content": {
                            "json": "### Application Gateways SSL Certificates (`microsoft.network/applicationgateways`)\r\nCentralized visibility into Application Gateway SSL termination certificates, identifying whether certificates are integrated with **Azure Key Vault for automated rotation** vs **direct manual file uploads**."
                        },
                        "name": "text - App Gateway Intro"
                    },
                    {
                        "type": 9,
                        "content": {
                            "version": "KqlParameterItem/1.0",
                            "parameters": [
                                {
                                    "id": "param-appgw-view",
                                    "version": "KqlParameterItem/1.0",
                                    "name": "AppGatewayView",
                                    "label": "Select View",
                                    "type": 2,
                                    "isRequired": true,
                                    "jsonData": "[\r\n {\"value\":\"live\", \"label\":\"Live Azure Resource Graph (Direct & Key Vault)\", \"selected\":true},\r\n {\"value\":\"loganalytics\", \"label\":\"Log Analytics Historical Decoded Table\"}\r\n]",
                                    "typeSettings": {
                                        "additionalResourceOptions": []
                                    }
                                }
                            ],
                            "style": "pills",
                            "queryType": 1,
                            "resourceType": "microsoft.resourcegraph/resources"
                        },
                        "name": "parameters - App Gateway View Selector"
                    },
                    {
                        "type": 3,
                        "content": {
                            "version": "KqlItem/1.0",
                            "query": "resources\n| where type =~ 'microsoft.network/applicationgateways'\n| mv-expand cert = properties.sslCertificates\n| extend certName = tostring(cert.name)\n| extend keyVaultSecretId = tostring(cert.properties.keyVaultSecretId)\n| extend certProvisioningState = tostring(cert.properties.provisioningState)\n| extend CertificateType = iff(isnotempty(keyVaultSecretId), 'Key Vault Managed', 'Direct Upload (Manual)')\n| extend AutoRotation = iff(isempty(keyVaultSecretId), 'None (Direct Upload)', iff(keyVaultSecretId matches regex @'/[0-9a-f]{32}$', 'Pinned Version (Manual Update)', 'Auto-Rotate (Unversioned URI)'))\n| extend TaggedExpiry = tostring(tags[strcat('CertExpiry_', certName)])\n| extend TaggedExpiryExact = tostring(tags[strcat('CertExpiryExact_', certName)])\n| extend TaggedDays = toint(tags[strcat('CertDays_', certName)])\n| extend TaggedStatus = tostring(tags[strcat('CertStatus_', certName)])\n| extend ExactExpirationDateTime = todatetime(TaggedExpiry)\n| extend ExactExpirationUTC = iff(isnotempty(TaggedExpiryExact), TaggedExpiryExact, iff(isnotempty(TaggedExpiry), TaggedExpiry, iff(isnotempty(keyVaultSecretId), 'Managed in Key Vault', 'Run sync script to decode')))\n| extend DaysRemaining = iff(isnotempty(TaggedDays), TaggedDays, iff(isnotempty(keyVaultSecretId), int(999), int(null)))\n| extend ExpiryStatus = iff(isnotempty(TaggedStatus), TaggedStatus, iff(isnotempty(keyVaultSecretId), 'Key Vault Managed', 'Direct Upload (Run sync script)'))\n| project ApplicationGateway = id, CertificateName = certName, ExactExpirationDateTime, ExactExpirationUTC, DaysRemaining, ExpiryStatus, CertificateType, AutoRotation, KeyVaultSecretURI = keyVaultSecretId, ProvisioningState = certProvisioningState, location, resourceGroup, subscriptionId\n| sort by CertificateType asc, CertificateName asc",
