                                        "formatOptions": {
                                            "thresholdsOptions": "icons",
                                            "thresholdsGrid": [
                                                {
                                                    "operator": "<=",
                                                    "thresholdValue": "0",
                                                    "representation": "3",
                                                    "text": "{0} Days (Expired)"
                                                },
                                                {
                                                    "operator": "<=",
                                                    "thresholdValue": "30",
                                                    "representation": "2",
